import React, { useEffect, useState } from "react";
import { useParams, useNavigate, useLocation } from "react-router-dom";
import Sidebar from "../components/Sidebar";
import "../styles/Lesson.css";

export default function Lesson() {
  const { lessonId } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const { lesson } = location.state || {};

  const [tutors, setTutors] = useState([]);
  const [sessions, setSessions] = useState([]);
  const [selectedTutor, setSelectedTutor] = useState(null);
  const [signupProcessing, setSignupProcessing] = useState(false);
  const [bookingStatus, setBookingStatus] = useState(null);
  const [bookedSession, setBookedSession] = useState(null);
  const [watchedVideos, setWatchedVideos] = useState({});
  const [currentVideoPlayer, setCurrentVideoPlayer] = useState(null);
  const [activeStep, setActiveStep] = useState(1);
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState(null);
  const [worksheet1Answers, setWorksheet1Answers] = useState({});
  const [worksheet2Answers, setWorksheet2Answers] = useState({});
  const [worksheet1Submitted, setWorksheet1Submitted] = useState(false);
  const [worksheet2Submitted, setWorksheet2Submitted] = useState(false);
  const [step3Completed, setStep3Completed] = useState(false);
  const [newQuestion, setNewQuestion] = useState("");
  const [newAnswer, setNewAnswer] = useState("");
  const [communityPosts, setCommunityPosts] = useState([
    {
      id: 1,
      author: "Alex Chen",
      type: "question",
      content: "Can someone explain the difference between mitosis and meiosis? I'm confused about when each process happens.",
      timestamp: "2 hours ago",
      replies: 5,
      likes: 12,
    },
    {
      id: 2,
      author: "Jordan Smith",
      type: "answer",
      content: "The scientific method is important because it provides a systematic approach to testing ideas and reducing bias in research. Each step helps ensure the results are reliable and reproducible.",
      timestamp: "1 hour ago",
      replies: 3,
      likes: 8,
    },
    {
      id: 3,
      author: "Maria Rodriguez",
      type: "question",
      content: "How does photosynthesis relate to cellular respiration? Are they opposite processes?",
      timestamp: "30 minutes ago",
      replies: 2,
      likes: 6,
    },
  ]);

  // Use videos from the lesson object if available, otherwise fallback to default Biology videos
  const defaultLessonVideos = [
    { id: 1, title: "Introduction to Biology", url: "https://www.youtube.com/watch?v=tZE_fQFK8EY&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=2" },
    { id: 2, title: "Scientific Method", url: "https://www.youtube.com/watch?v=xOLcZMw0hd4&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=3" },
    { id: 3, title: "What do Biologists Do?", url: "https://www.youtube.com/watch?v=rgZhDoPgzK8&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=4" },
    { id: 4, title: "Organized Life", url: "https://www.youtube.com/watch?v=cjR5zPrVjTc&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=5" },
    { id: 5, title: "Introduction to Ecology", url: "https://www.youtube.com/watch?v=aO3Yp45zmw8&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=6" },
  ];

  const lessonVideos = lesson?.videos || defaultLessonVideos;

  // Create detailed worksheets based on lesson content - SIMPLIFIED
  const createDetailedWorksheets = (videos, lessonTitle) => {
    // Map lesson titles to 10 questions covering all videos in that lesson
    const worksheetMap = {
      // Biology Lesson 1: Introduction to Biology (5 videos)
      "Introduction to Biology": [
        { id: 1, question: "What is the primary definition of biology?", options: ["The study of chemistry", "The scientific study of life and living organisms", "The study of fossils", "The study of rocks"], correct: 1 },
        { id: 2, question: "Which of the following is a characteristic of all living organisms?", options: ["They are stationary", "They are made of cells", "They never change", "They exist only on land"], correct: 1 },
        { id: 3, question: "What do all living things have in common?", options: ["Wings", "DNA and cells", "The ability to fly", "Fur or scales"], correct: 1 },
        { id: 4, question: "What is the smallest unit of life?", options: ["Atom", "Molecule", "Cell", "Organism"], correct: 2 },
        { id: 5, question: "What is homeostasis?", options: ["A type of evolution", "An organism's ability to maintain stable internal conditions", "A disease", "A geographic location"], correct: 1 },
        { id: 6, question: "Do all organisms reproduce?", options: ["Only animals", "Only plants", "All living organisms reproduce", "Only some bacteria"], correct: 2 },
        { id: 7, question: "What is the scientific method?", options: ["Guessing randomly", "A systematic process for testing ideas", "Only for physics", "No real method"], correct: 1 },
        { id: 8, question: "What is ecology the study of?", options: ["Only rocks", "Organisms and their interactions with the environment", "Weather only", "Chemistry"], correct: 1 },
        { id: 9, question: "How many main branches of biology are there?", options: ["2", "3", "Many different specialized branches", "Just one"], correct: 2 },
        { id: 10, question: "What is the fundamental unit of organization in all living things?", options: ["Tissue", "Organ", "The cell", "System"], correct: 2 }
      ],
      // Biology Lesson 2: Ecology
      "Community Ecology": [
        { id: 1, question: "What is community ecology?", options: ["Only studying human communities", "The study of how different species interact in a shared environment", "The study of just one species", "Urban planning"], correct: 1 },
        { id: 2, question: "What is competition in an ecosystem?", options: ["Friendly cooperation", "Organisms struggling for the same resources", "Predation", "Decomposition"], correct: 1 },
        { id: 3, question: "What is predation?", options: ["Competition for food", "One organism eating another", "Mutual benefit", "Decomposition"], correct: 1 },
        { id: 4, question: "What is mutualism?", options: ["One organism benefits", "Both organisms benefit from the relationship", "One is harmed", "Neither is affected"], correct: 1 },
        { id: 5, question: "What is parasitism?", options: ["Mutual benefit", "One organism benefits while the other is harmed", "Both are harmed", "Neither is affected"], correct: 1 },
        { id: 6, question: "What determines species composition in a community?", options: ["Random factors only", "Physical environment, competition, and predation", "Just luck", "Only temperature"], correct: 1 },
        { id: 7, question: "What is a food chain?", options: ["Stores selling food", "A sequence showing how energy flows from organism to organism", "Just plants", "Only animals"], correct: 1 },
        { id: 8, question: "What is the role of decomposers?", options: ["Creating food", "Breaking down dead matter and recycling nutrients", "Predation", "Fixing nitrogen"], correct: 1 },
        { id: 9, question: "Can two species occupy the same niche?", options: ["Always", "Generally not, they'll compete until one is excluded", "Only in water", "Only on land"], correct: 1 },
        { id: 10, question: "What increases biodiversity in a community?", options: ["Removing all organisms", "Having diverse habitats and reduced competition", "Pollution", "Monocultures"], correct: 1 }
      ],
      "Population Ecology": [
        { id: 1, question: "What is population ecology?", options: ["Study of human cities", "The study of populations and their dynamics", "Study of single organisms", "Study of behavior only"], correct: 1 },
        { id: 2, question: "What is population growth?", options: ["Individuals getting larger", "Increase in the number of individuals over time", "Only reproduction", "Migration only"], correct: 1 },
        { id: 3, question: "What is the carrying capacity?", options: ["What an organism can carry", "The maximum population size an environment can support", "Birth rate", "Immigration rate"], correct: 1 },
        { id: 4, question: "What happens when a population exceeds carrying capacity?", options: ["It keeps growing", "The population declines due to resource scarcity", "Nothing changes", "It doubles"], correct: 1 },
        { id: 5, question: "What is birth rate?", options: ["The age of organisms", "The number of new individuals born per unit time", "Death of organisms", "Movement"], correct: 1 },
        { id: 6, question: "What is death rate?", options: ["Birth of organisms", "The number of organisms dying per unit time", "Population growth", "Immigration"], correct: 1 },
        { id: 7, question: "What is immigration?", options: ["Leaving a population", "Movement into a population", "Death", "Birth"], correct: 1 },
        { id: 8, question: "What factors limit population growth?", options: ["None, unlimited growth", "Food, space, disease, predation", "Only food", "Only predators"], correct: 1 },
        { id: 9, question: "What is logistic growth?", options: ["Exponential forever", "Growth that slows as carrying capacity is reached", "No growth", "Decline only"], correct: 1 },
        { id: 10, question: "How do density-dependent factors affect populations?", options: ["Never affect them", "Their effect increases with population density", "Always decrease populations", "Only in forests"], correct: 1 }
      ],
      "What is Climate Change?": [
        { id: 1, question: "What is climate change?", options: ["Weather getting warmer for one day", "Long-term shifts in global temperature and weather patterns", "Not happening", "Only seasonal variation"], correct: 1 },
        { id: 2, question: "What is the greenhouse effect?", options: ["Effect of plant growth", "Trapping of heat by atmospheric gases leading to warming", "Cooling the planet", "Only happens at night"], correct: 1 },
        { id: 3, question: "Which gas is primarily responsible for climate change?", options: ["Oxygen", "Nitrogen", "Carbon dioxide", "Helium"], correct: 2 },
        { id: 4, question: "What is the main human cause of climate change?", options: ["Animal breathing", "Burning of fossil fuels", "Plant growth", "Ocean waves"], correct: 1 },
        { id: 5, question: "Is climate change natural?", options: ["Entirely natural", "Primarily caused by human activities", "Doesn't exist", "Only happens in deserts"], correct: 1 },
        { id: 6, question: "What is the difference between climate and weather?", options: ["They're the same", "Climate is long-term patterns, weather is short-term", "Weather is more important", "No difference"], correct: 1 },
        { id: 7, question: "What evidence shows climate is changing?", options: ["Just computer models", "Rising temperatures, melting ice, sea level rise", "No evidence", "Only in cities"], correct: 1 },
        { id: 8, question: "Can we slow climate change?", options: ["No, it's inevitable", "Yes, through reducing emissions and conservation", "It will stop on its own", "Only governments can"], correct: 1 },
        { id: 9, question: "What is a carbon footprint?", options: ["A footprint on carbon", "The total greenhouse gases produced by an activity", "Size of feet", "Only factories have them"], correct: 1 },
        { id: 10, question: "What year did the Paris Climate Accord occur?", options: ["2000", "2010", "2015", "2025"], correct: 2 }
      ],
      "The Effects of Climate Change": [
        { id: 1, question: "What is a major effect of climate change on ecosystems?", options: ["No changes", "Species extinction, habitat loss, ecosystem disruption", "Ecosystem improvement", "Only affects humans"], correct: 1 },
        { id: 2, question: "How does climate change affect sea levels?", options: ["Levels stay constant", "Warming causes ice melt and water expansion, raising levels", "Levels decrease", "No effect"], correct: 1 },
        { id: 3, question: "What happens to coral reefs with warming oceans?", options: ["They grow faster", "Bleaching occurs, threatening the ecosystem", "No effect", "They become stronger"], correct: 1 },
        { id: 4, question: "How does climate change affect agriculture?", options: ["Increases all crops", "Alters growing seasons and threatens food security", "No effect on farming", "Only helps farming"], correct: 1 },
        { id: 5, question: "What is ocean acidification?", options: ["Oceans becoming salty", "Increased CO2 absorption making oceans more acidic", "Oceans becoming basic", "Not happening"], correct: 1 },
        { id: 6, question: "Which species are most threatened by climate change?", options: ["Only large animals", "Species in extreme habitats like polar and mountain regions", "Introduced species only", "No species affected"], correct: 1 },
        { id: 7, question: "How does climate change affect human health?", options: ["No effects", "Through heat stress, disease vectors, and food security", "Only positive effects", "Not related"], correct: 1 },
        { id: 8, question: "What are tipping points in climate?", options: ["Points where nothing changes", "Critical thresholds where change accelerates drastically", "The coldest points", "Only in ice ages"], correct: 1 },
        { id: 9, question: "Can extreme weather be linked to climate change?", options: ["Never", "Yes, warming increases frequency of extreme events", "Only in summer", "Only in winter"], correct: 1 },
        { id: 10, question: "What is climate migration?", options: ["Seasonal animal movement", "Movement of people due to climate impacts", "Tourism only", "Not occurring"], correct: 1 }
      ],
      "Conservation Biology": [
        { id: 1, question: "What is conservation biology?", options: ["Preserving buildings", "The science of protecting biodiversity and ecosystems", "Only protecting animals", "Not a real science"], correct: 1 },
        { id: 2, question: "What is habitat loss?", options: ["Animals losing weight", "Destruction of natural habitats threatening species", "Not a problem", "Only in cities"], correct: 1 },
